// ===== eingebettet aus src/freigabe.js – nicht hier bearbeiten, sondern im Repo (npm run build) =====
const freigabe = (() => {
const module = { exports: {} };
// Freigabe Variante B (Bauplan 6): einmaliges, ablaufendes Token je Freigeber. Gespeichert wird nur der
// SHA-256-Hash. Der Endpunkt EPA-07 zeigt ein Formular (Vorschau, Text bearbeitbar, Senden/Ablehnen) und
// verbraucht die Freigabe atomar (bedingtes Update auf status = 'offen').

const TOKEN_MUSTER = /^[A-Za-z0-9_-]{43}$/; // 32 Byte base64url
const AKTIONEN = ['senden', 'ablehnen'];

/** @param {object} c Node-Modul "crypto" (im Code-Node per require('crypto')) */
function tokenErzeugen(c) {
	const token = c.randomBytes(32).toString('base64url');
	return { token, hash: tokenHash(c, token) };
}

function tokenHash(c, token) {
	return c.createHash('sha256').update(String(token), 'utf8').digest('hex');
}

function freigabeIdErzeugen(c) {
	return 'F-' + c.randomUUID();
}

function istGueltigesToken(t) {
	return typeof t === 'string' && TOKEN_MUSTER.test(t);
}

/** Basis-URL der Instanz aus $execution.resumeUrl (…/webhook-waiting/<id>) bzw. einem Override. */
function basisUrl(resumeUrl, override) {
	if (override) return String(override).replace(/\/+$/, '');
	const m = String(resumeUrl || '').match(/^(https?:\/\/[^/]+(?:\/[^/]+)*?)\/webhook-waiting\//);
	if (!m) throw new Error('Basis-URL der Instanz nicht ermittelbar');
	return m[1];
}

function link(basis, token) {
	return `${basis}/webhook/epa-freigabe?t=${encodeURIComponent(token)}`;
}

/**
 * Prüft Token und Freigabe vor Anzeige bzw. Entscheidung.
 * @returns {{ ok: true } | { ok: false, status: number, code: string, meldung: string }}
 */
function freigabePruefen({ token, freigabe, freigeberErlaubt, jetzt }) {
	const nein = (status, code, meldung) => ({ ok: false, status, code, meldung });
	if (!token || token.id === undefined) return nein(404, 'NICHT_GEFUNDEN', 'Dieser Freigabe-Link ist ungültig.');
	if (!freigabe || freigabe.id === undefined) return nein(404, 'NICHT_GEFUNDEN', 'Die Freigabe existiert nicht mehr.');
	if (freigabe.status !== 'offen') {
		const wer = freigabe.entscheider ? ` von ${freigabe.entscheider}` : '';
		const was = { in_versand: 'wird gerade versendet', gesendet: 'wurde bereits freigegeben und gesendet', abgelehnt: 'wurde bereits abgelehnt', abgelaufen: 'ist abgelaufen', ersetzt: 'wurde durch eine neuere Freigabe ersetzt', fehler: 'ist beim Versand fehlgeschlagen', unzustellbar: 'wurde gesendet, kam beim Kunden aber nicht an', nicht_zugestellt: 'wurde gesendet, kam beim Kunden aber nicht an' }[freigabe.status] || `hat den Status "${freigabe.status}"`;
		// Betreff nennen, damit klar ist, um welche Anfrage es geht (mehrere Links in einem Chat).
		const betrifft = freigabe.betreff ? ` Betrifft: ${String(freigabe.betreff).slice(0, 150)}` : '';
		return nein(freigabe.status === 'abgelaufen' ? 410 : 409, freigabe.status === 'abgelaufen' ? 'FREIGABE_ABGELAUFEN' : 'DUPLIKAT', `Diese ${freigabe.art === 'erinnerung' ? 'Erinnerung' : 'Rückfrage'} ${was}${freigabe.status === 'gesendet' || freigabe.status === 'abgelehnt' ? wer : ''}.${betrifft}`);
	}
	if (token.verbraucht_am) return nein(409, 'DUPLIKAT', 'Dieser Link wurde bereits verwendet.');
	if (new Date(freigabe.ablauf).getTime() <= new Date(jetzt).getTime()) return nein(410, 'FREIGABE_ABGELAUFEN', 'Dieser Freigabe-Link ist abgelaufen. Ein neuer Link wird automatisch verschickt.');
	// Ab M5: Links haben eine eigene Ablaufzeit. Bei der Erneuerung einer abgelaufenen Freigabe werden alle alten Links gesperrt.
	if (token.ablauf && new Date(token.ablauf).getTime() <= new Date(jetzt).getTime()) return nein(410, 'FREIGABE_ABGELAUFEN', 'Dieser Freigabe-Link ist abgelaufen. Sie haben inzwischen einen neuen Link erhalten.');
	if (!freigeberErlaubt) return nein(403, 'KEINE_BERECHTIGUNG', 'Sie sind für diesen Kunden nicht (mehr) als Freigeber eingetragen.');
	return { ok: true };
}

/** Formulardaten aus EPA-07 (POST, application/x-www-form-urlencoded). */
function formularLesen(body) {
	const b = body && typeof body === 'object' ? body : {};
	const aktion = String(b.aktion || '');
	if (!AKTIONEN.includes(aktion)) return { ok: false, meldung: 'Unbekannte Aktion.' };
	if (!istGueltigesToken(b.t)) return { ok: false, meldung: 'Ungültiger Link.' };
	const grund = String(b.grund || '').trim().slice(0, 500);
	if (aktion === 'ablehnen' && !grund) return { ok: false, meldung: 'Bitte einen Grund für die Ablehnung angeben.' };
	return { ok: true, aktion, token: b.t, text: typeof b.text === 'string' ? b.text : '', grund };
}

function istBearbeitet(original, neu) {
	const n = (s) => String(s ?? '').replace(/\r\n?/g, '\n').replace(/[ \t]+/g, ' ').replace(/\s+$/gm, '').trim();
	return n(original) !== n(neu);
}

// ---------------------------------------------------------------- HTML

function esc(s) {
	return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
}

const STIL = `body{font-family:system-ui,-apple-system,Segoe UI,Arial,sans-serif;margin:0;background:#f4f5f7;color:#1d2433}
main{max-width:760px;margin:0 auto;padding:16px}
.karte{background:#fff;border-radius:8px;padding:20px;box-shadow:0 1px 3px rgba(0,0,0,.08);margin-bottom:16px}
h1{font-size:1.3rem;margin:0 0 12px}dl{display:grid;grid-template-columns:max-content 1fr;gap:4px 12px;margin:0}
dt{color:#5b6475}dd{margin:0;overflow-wrap:anywhere}textarea{width:100%;box-sizing:border-box;min-height:260px;font:inherit;padding:8px}
pre{white-space:pre-wrap;font:inherit;color:#5b6475;margin:8px 0 0}.knoepfe{display:flex;gap:12px;flex-wrap:wrap;margin-top:12px}
button{font:inherit;padding:10px 16px;border-radius:6px;border:0;cursor:pointer}.senden{background:#1f6f43;color:#fff}.ablehnen{background:#a3222b;color:#fff}
input[type=text]{width:100%;box-sizing:border-box;font:inherit;padding:8px}.hinweis{color:#5b6475;font-size:.9rem}
.ok{border-left:4px solid #1f6f43}.fehler{border-left:4px solid #a3222b}`;

function seite(titel, inhalt) {
	return `<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${esc(titel)}</title><style>${STIL}</style></head><body><main>${inhalt}</main></body></html>`;
}

function seiteFormular({ token, freigabe, vorgang, fehlende, text, abschluss }) {
	const luecken = (fehlende || []).map((f) => `<li>${esc(f.anzeigename)}${f.grund ? ` <span class="hinweis">(${esc(f.grund)})</span>` : ''}</li>`).join('');
	const was = freigabe.art === 'erinnerung' ? 'Erinnerung' : 'Rückfrage';
	return seite(`${was} ${vorgang.vorgangs_id}`, `
<div class="karte"><h1>${was} freigeben – ${esc(vorgang.vorgangs_id)}</h1>
<dl><dt>An</dt><dd>${esc(freigabe.empfaenger)}</dd><dt>Betreff</dt><dd>${esc(freigabe.betreff)}</dd>
<dt>Runde</dt><dd>${esc(Number(vorgang.rundenzaehler || 0) + 1)}</dd><dt>Gültig bis</dt><dd>${esc(new Date(freigabe.ablauf).toLocaleString('de-DE', { timeZone: 'Europe/Berlin' }))}</dd></dl>
<p>Fehlende Angaben:</p><ul>${luecken}</ul>${freigabe.fallback ? '<p class="hinweis">Hinweis: Die KI-Formulierung hat die Prüfung nicht bestanden, es wird die Standardvorlage verwendet.</p>' : ''}</div>
<form class="karte" method="post" onsubmit="var f=this;setTimeout(function(){var b=f.querySelectorAll('button');for(var i=0;i<b.length;i++)b[i].disabled=true},0)">
<input type="hidden" name="t" value="${esc(token)}">
<label for="text"><b>Text der Mail</b> (bearbeitbar)</label>
<textarea id="text" name="text">${esc(text)}</textarea>
<pre>${esc(abschluss)}</pre>
<p class="hinweis">Signatur und KI-Hinweis werden immer automatisch angehängt.</p>
<label for="grund">Grund (nur bei Ablehnung)</label><input type="text" id="grund" name="grund" maxlength="500">
<div class="knoepfe"><button class="senden" name="aktion" value="senden">Freigeben und senden</button>
<button class="ablehnen" name="aktion" value="ablehnen">Ablehnen (manuell bearbeiten)</button></div>
<p class="hinweis">Der Link ist nur einmal verwendbar. Nichts wird ohne Ihren Klick versendet.</p></form>`);
}

function seiteMeldung(titel, text, art = 'ok') {
	return seite(titel, `<div class="karte ${art === 'ok' ? 'ok' : 'fehler'}"><h1>${esc(titel)}</h1><p>${esc(text)}</p></div>`);
}

/** Teams-Nachricht an den Freigeber (1:1-Chat). */
const ANLASS = Object.freeze({
	freigabe_erinnerung: 'Erinnerung: Diese Freigabe ist noch offen. Hier ist ein neuer persönlicher Link.',
	freigabe_erneuern: 'Der bisherige Link ist abgelaufen und gilt nicht mehr. Hier ist ein neuer persönlicher Link.',
	freigabe_nach_fehler: 'Diese Nachricht wurde wegen eines Fehlers NICHT gesendet. Das Postfach ist wieder erreichbar, bitte erneut freigeben. Die bisherigen Links gelten nicht mehr.',
	freigabe_eskalation: 'Bitte jetzt entscheiden: freigeben, bearbeiten oder ablehnen. Hier ist ein neuer persönlicher Link; alle bisherigen Links gelten nicht mehr.',
	freigabe_nach_unzustellbar: 'Der Zustelltest war wieder erfolgreich, der Versand funktioniert. Bitte prüfen und erneut freigeben; gesendet wird eine neue Mail mit demselben Text.',
});

/**
 * Nachricht an einen Freigeber. kontext_html (optional, vom Aufrufer erzeugt, bereits escaped) ist die Übersicht
 * zur Mail (erkannte und fehlende Angaben, Warnhinweise). Dann ersetzt diese eine Nachricht die sonst zusätzliche
 * Eingangsmeldung, und die Liste der fehlenden Angaben steht nicht doppelt drin.
 */
function nachrichtFreigeber({ vorgang, freigabe, fehlende, link: url, ablaufText, art, anlass, kontext_html: kontext, wartet_stunden: wartet }) {
	const liste = (fehlende || []).map((f) => `• ${esc(f.anzeigename)}`).join('<br>');
	const was = art === 'erinnerung' ? 'Erinnerung' : 'Rückfrage';
	let hinweis = ANLASS[anlass] ? `<i>${esc(ANLASS[anlass])}</i><br>` : '';
	if (anlass === 'freigabe_nach_fehler') {
		hinweis = `<b>🔁 Erneut zur Freigabe: Versand war fehlgeschlagen</b><br>${freigabe.grund ? `Grund: ${esc(freigabe.grund)}<br>` : ''}${hinweis}<br>`;
	} else if (anlass === 'freigabe_eskalation') {
		const dauer = Number.isFinite(Number(wartet)) && wartet !== null ? `seit ${Number(wartet)} Stunden` : 'seit längerer Zeit';
		hinweis = `<b>⏰ Eskalation: Diese Freigabe wartet ${esc(dauer)}</b><br>Der Kunde hat noch keine Antwort bekommen.<br>${hinweis}<br>`;
	} else if (anlass === 'freigabe_nach_unzustellbar') {
		// freigabe.grund trägt hier den Grund der vorigen (nicht zugestellten) Freigabe.
		hinweis = `<b>🔁 Erneut zur Freigabe: Die Nachricht kam beim Kunden nicht an</b><br>${freigabe.grund ? `${esc(freigabe.grund)}<br>` : ''}${hinweis}<br>`;
	}
	const link = `<a href="${esc(url)}">Entwurf ansehen, bearbeiten oder freigeben</a><br><i>Dieser persönliche Link ist einmal verwendbar und gültig bis ${esc(ablaufText)}. Bitte nicht weiterleiten.</i>`;
	const empfang = `An: ${esc(freigabe.empfaenger)}<br>Betreff: ${esc(freigabe.betreff)}<br><br>`;
	if (kontext && typeof kontext === 'string' && kontext.trim()) {
		return `${hinweis}${kontext}<br><br><b>${was} an den Kunden wurde erstellt</b><br>${empfang}${link}`;
	}
	return `${hinweis}<b>${was} an den Kunden freigeben</b><br><br>Vorgangsnummer: <b>${esc(vorgang.vorgangs_id)}</b><br>${empfang}` +
		(liste ? `<b>Fehlende Angaben</b><br>${liste}<br><br>` : '') + link;
}

module.exports = {
	TOKEN_MUSTER, AKTIONEN, tokenErzeugen, tokenHash, freigabeIdErzeugen, istGueltigesToken, basisUrl, link,
	freigabePruefen, formularLesen, istBearbeitet, esc, seite, seiteFormular, seiteMeldung, nachrichtFreigeber, ANLASS,
};
return module.exports;
})();
// ===== Ende src/freigabe.js =====

// ----- Node-Logik -----
const crypto = require('crypto');
const j = $input.first().json;
const body = j.body && typeof j.body === 'object' ? j.body : {};
const post = Object.prototype.hasOwnProperty.call(body, 'aktion') || Object.prototype.hasOwnProperty.call(body, 't');
const token = String(post ? body.t || '' : (j.query || {}).t || '');
const gueltig = freigabe.istGueltigesToken(token);
return [{ json: { methode: post ? 'POST' : 'GET', token, gueltig, body: post ? body : null, hash: gueltig ? freigabe.tokenHash(crypto, token) : '__ungueltig__' } }];

// ===== eingebettet aus src/kalender.js – nicht hier bearbeiten, sondern im Repo (npm run build) =====
const kalender = (() => {
const module = { exports: {} };
// Kalenderprüfung für Terminanfragen (Config "kalender"): Ist der Wunschtermin im Outlook-Kalender des Kunden frei?
// Das Team bekommt eine Meldung mit Link; eingetragen wird erst nach Klick (EPA-15). Der Agent trägt nie selbst ein
// und schreibt dem Kunden nichts. Reine Funktionen, keine Abhängigkeiten (Zeitzonen über Intl).

const STANDARD = Object.freeze({ dauer_minuten: 60, gueltig_stunden: 72 });
const ZEITRAEUME = Object.freeze({
	vormittag: ['08:00', '12:00'],
	mittag: ['11:00', '14:00'],
	nachmittag: ['13:00', '17:00'],
	abend: ['17:00', '20:00'],
});
const MAX_VORSCHLAEGE = 3;
const RASTER_MINUTEN = 30;
const TAGE = ['So', 'Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa'];

function zwei(n) {
	return String(n).padStart(2, '0');
}

function zeitOk(h, m) {
	return Number.isInteger(h) && Number.isInteger(m) && h >= 0 && h <= 23 && m >= 0 && m <= 59;
}

function hhmm(h, m) {
	return `${zwei(h)}:${zwei(m)}`;
}

function minuten(zeit) {
	const [h, m] = String(zeit).split(':').map(Number);
	return h * 60 + m;
}

function ausMinuten(n) {
	return hhmm(Math.floor(n / 60), n % 60);
}

function mitAmPm(h, ampm) {
	if (!ampm) return h;
	const a = ampm.toLowerCase().replace(/\./g, '');
	if (a === 'pm' && h < 12) return h + 12;
	if (a === 'am' && h === 12) return 0;
	return h;
}

/**
 * Liest eine frei geschriebene Uhrzeit ("10 Uhr", "10:30", "14.00", "2 pm", "zwischen 9 und 11", "vormittags").
 * @returns {{ art: 'exakt', von: string } | { art: 'zeitraum', von: string, bis: string } | null}
 */
function uhrzeitLesen(text) {
	const t = String(text ?? '').toLowerCase().trim();
	if (!t) return null;
	const AP = '\\s*(a\\.?m\\.?|p\\.?m\\.?)?';
	// Spanne: "9-11 Uhr", "9:30 – 11", "zwischen 9 und 11 Uhr", "from 9 to 11 am"
	const spanne = t.match(new RegExp(`(\\d{1,2})(?:[:.](\\d{2}))?${AP}\\s*(?:-|–|bis|und|to)\\s*(\\d{1,2})(?:[:.](\\d{2}))?${AP}\\s*(?:uhr|h\\b)?`));
	if (spanne && (/zwischen|between|from|von|uhr|h\b|[:.]\d{2}|am|pm/.test(t))) {
		const h1 = mitAmPm(Number(spanne[1]), spanne[3] || spanne[6]);
		const m1 = Number(spanne[2] || 0);
		const h2 = mitAmPm(Number(spanne[4]), spanne[6]);
		const m2 = Number(spanne[5] || 0);
		if (zeitOk(h1, m1) && zeitOk(h2, m2) && h2 * 60 + m2 > h1 * 60 + m1) return { art: 'zeitraum', von: hhmm(h1, m1), bis: hhmm(h2, m2) };
	}
	const mitMinuten = t.match(new RegExp(`(\\d{1,2})[:.](\\d{2})${AP}`));
	if (mitMinuten) {
		const h = mitAmPm(Number(mitMinuten[1]), mitMinuten[3]);
		const m = Number(mitMinuten[2]);
		if (zeitOk(h, m)) return { art: 'exakt', von: hhmm(h, m) };
	}
	const volle = t.match(/(\d{1,2})\s*(uhr|h\b|a\.?m\.?|p\.?m\.?|o'?clock)/) || t.match(/(?:^|\b)(?:um|ab|gegen|at|around)\s+(\d{1,2})\b/) || t.match(/^(\d{1,2})$/);
	if (volle) {
		const h = mitAmPm(Number(volle[1]), /^[ap]/.test(volle[2] || '') ? volle[2] : null);
		if (zeitOk(h, 0)) return { art: 'exakt', von: hhmm(h, 0) };
	}
	const WOERTER = [
		[/vormittag|morgens|morning/, 'vormittag'],
		[/nachmittag|afternoon/, 'nachmittag'],
		[/mittag|noon|lunch/, 'mittag'],
		[/abend|evening/, 'abend'],
	];
	for (const [re, name] of WOERTER) if (re.test(t)) return { art: 'zeitraum', von: ZEITRAEUME[name][0], bis: ZEITRAEUME[name][1], name };
	return null;
}

/** Abstand der Zeitzone zu UTC in Minuten an diesem Tag und dieser Uhrzeit (Sommerzeit beachtet). */
function offsetMinuten(datum, zeit, zone) {
	const [j, mo, t] = datum.split('-').map(Number);
	const [h, mi] = zeit.split(':').map(Number);
	let utc = Date.UTC(j, mo - 1, t, h, mi);
	// Zweimal annähern, damit auch Zeiten kurz nach der Umstellung stimmen.
	for (let i = 0; i < 2; i++) {
		const teile = new Intl.DateTimeFormat('en-US', { timeZone: zone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' })
			.formatToParts(new Date(utc)).reduce((o, p) => ({ ...o, [p.type]: p.value }), {});
		const lokal = Date.UTC(Number(teile.year), Number(teile.month) - 1, Number(teile.day), Number(teile.hour), Number(teile.minute));
		const off = Math.round((lokal - utc) / 60000);
		utc = Date.UTC(j, mo - 1, t, h, mi) - off * 60000;
		if (i === 1) return off;
	}
	return 0;
}

/** Lokale Zeit -> ISO mit Offset, z. B. 2026-12-03T10:00:00+01:00 */
function zuIso(datum, zeit, zone) {
	const off = offsetMinuten(datum, zeit, zone);
	const v = off < 0 ? '-' : '+';
	const a = Math.abs(off);
	return `${datum}T${zeit}:00${v}${zwei(Math.floor(a / 60))}:${zwei(a % 60)}`;
}

/** Zeitpunkt (ms) -> lokale "HH:MM" bzw. "JJJJ-MM-TT" in der Zone */
function lokal(ms, zone) {
	const p = new Intl.DateTimeFormat('en-CA', { timeZone: zone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' })
		.formatToParts(new Date(ms)).reduce((o, x) => ({ ...o, [x.type]: x.value }), {});
	return { datum: `${p.year}-${p.month}-${p.day}`, zeit: `${p.hour}:${p.minute}` };
}

function wochentag(datum) {
	const [j, m, t] = datum.split('-').map(Number);
	return new Date(Date.UTC(j, m - 1, t)).getUTCDay();
}

function datumText(datum) {
	const [j, m, t] = datum.split('-');
	return `${TAGE[wochentag(datum)]} ${t}.${m}.${j}`;
}

function wert(vorgang, feld) {
	if (!feld) return null;
	const d = vorgang && vorgang.extrahierte_daten && vorgang.extrahierte_daten[feld];
	const w = d && typeof d === 'object' ? d.wert : d;
	return w === null || w === undefined || w === '' ? null : String(w).trim();
}

/** Config "kalender" (bereits geprüft) mit Standardwerten. */
function einstellungen(config) {
	const k = (config && config.kalender) || null;
	if (!k || k.aktiv !== true) return null;
	return { ...STANDARD, ...k };
}

/**
 * Was soll geprüft werden? Liefert { relevant: false, grund } oder den Plan mit Prüffenster (ISO mit Offset).
 * @param {object} config geprüfte Kunden-Config (kalender, zeitzone, geschaeftszeiten)
 * @param {object} vorgang Vorgang mit vorgangstyp und extrahierte_daten
 * @param {string} jetztIso aktueller Zeitpunkt
 */
function plan(config, vorgang, jetztIso) {
	const k = einstellungen(config);
	if (!k) return { relevant: false, grund: 'Kalender nicht eingerichtet' };
	if (!vorgang || vorgang.vorgangstyp !== k.vorgangstyp) return { relevant: false, grund: 'andere Vorgangsart' };
	const datum = wert(vorgang, k.datum_feld);
	if (!datum || !/^\d{4}-\d{2}-\d{2}$/.test(datum)) return { relevant: false, grund: 'kein Datum' };
	const zone = config.zeitzone || 'Europe/Berlin';
	const gz = config.geschaeftszeiten || { tage: [1, 2, 3, 4, 5], von: '08:00', bis: '17:00' };
	const uhr = uhrzeitLesen(wert(vorgang, k.uhrzeit_feld));
	const dauer = Number(k.dauer_minuten);
	const hinweise = [];
	let art;
	let von;
	let bis;
	if (uhr && uhr.art === 'exakt') {
		art = 'exakt';
		von = uhr.von;
		bis = ausMinuten(Math.min(minuten(von) + dauer, 23 * 60 + 59));
	} else {
		art = 'zeitraum';
		von = uhr ? uhr.von : gz.von;
		bis = uhr ? uhr.bis : gz.bis;
		if (!uhr) hinweise.push('Keine genaue Uhrzeit genannt – geprüft wurde die Geschäftszeit an diesem Tag.');
		if (minuten(bis) - minuten(von) < dauer) bis = ausMinuten(Math.min(minuten(von) + dauer, 23 * 60 + 59));
	}
	const startIso = zuIso(datum, von, zone);
	const endeIso = zuIso(datum, bis, zone);
	if (new Date(endeIso).getTime() <= new Date(jetztIso).getTime()) hinweise.push('Der Wunschtermin liegt in der Vergangenheit.');
	if (Array.isArray(gz.tage) && !gz.tage.includes(wochentag(datum) === 0 ? 7 : wochentag(datum))) hinweise.push('Der Wunschtermin liegt außerhalb Ihrer Geschäftstage.');
	else if (art === 'exakt' && (minuten(von) < minuten(gz.von) || minuten(bis) > minuten(gz.bis))) hinweise.push('Der Wunschtermin liegt außerhalb Ihrer Geschäftszeit.');
	return {
		relevant: true,
		art,
		datum,
		von,
		bis,
		dauer_minuten: dauer,
		zone,
		start_iso: startIso,
		ende_iso: endeIso,
		titel: wert(vorgang, k.titel_feld) || 'Termin',
		ort: wert(vorgang, k.ort_feld),
		uhrzeit_text: wert(vorgang, k.uhrzeit_feld),
		hinweise,
	};
}

/** Graph-Zeitangabe ({ dateTime, timeZone }) -> ms. Ohne Prefer-Header liefert Graph UTC. */
function graphZeit(z) {
	if (!z || !z.dateTime) return NaN;
	const s = String(z.dateTime).replace(/(\.\d{3})\d*$/, '$1');
	const utc = !z.timeZone || /^(utc|etc\/utc|gmt)$/i.test(z.timeZone);
	return new Date(utc && !/[zZ]|[+-]\d{2}:\d{2}$/.test(s) ? `${s}Z` : s).getTime();
}

/** Belegte Zeiten aus der Graph-Antwort (calendarView). "Frei" markierte und abgesagte Termine zählen nicht. */
function belegt(ereignisse) {
	return (Array.isArray(ereignisse) ? ereignisse : [])
		.filter((e) => e && e.isCancelled !== true && String(e.showAs || 'busy').toLowerCase() !== 'free')
		.map((e) => ({ von: graphZeit(e.start), bis: graphZeit(e.end), ganztags: e.isAllDay === true }))
		.filter((e) => Number.isFinite(e.von) && Number.isFinite(e.bis) && e.bis > e.von)
		.sort((a, b) => a.von - b.von);
}

/**
 * Bewertet die Kalenderdaten zum Plan.
 * @returns {{ frei: boolean, konflikte: Array<{von: string, bis: string, ganztags: boolean}>, vorschlaege: Array<{start_iso: string, ende_iso: string, text: string}> }}
 */
function bewerten(p, ereignisse) {
	const zone = p.zone;
	const b = belegt(ereignisse);
	const ueberschneidet = (s, e) => b.some((x) => x.von < e && x.bis > s);
	const start = new Date(p.start_iso).getTime();
	const ende = new Date(p.ende_iso).getTime();
	const dauer = p.dauer_minuten * 60000;
	const konflikte = b.filter((x) => x.von < ende && x.bis > start).map((x) => ({ von: lokal(x.von, zone).zeit, bis: lokal(x.bis, zone).zeit, ganztags: x.ganztags }));
	const vorschlaege = [];
	const slot = (s) => {
		const e = s + dauer;
		vorschlaege.push({ start_iso: new Date(s).toISOString(), ende_iso: new Date(e).toISOString(), text: `${datumText(p.datum)}, ${lokal(s, zone).zeit}–${lokal(e, zone).zeit} Uhr` });
	};
	if (p.art === 'exakt') {
		const frei = !ueberschneidet(start, start + dauer);
		if (frei) slot(start);
		return { frei, konflikte, vorschlaege };
	}
	for (let s = start; s + dauer <= ende && vorschlaege.length < MAX_VORSCHLAEGE; s += RASTER_MINUTEN * 60000) {
		if (!ueberschneidet(s, s + dauer)) slot(s);
	}
	return { frei: vorschlaege.length > 0, konflikte, vorschlaege };
}

/** Freie Zeiten außerhalb des Wunschfensters am selben Tag (nur wenn der Wunsch belegt ist). */
function ausweichen(p, ereignisse, gz) {
	const zone = p.zone;
	const g = gz || { von: '08:00', bis: '17:00' };
	const b = belegt(ereignisse);
	const dauer = p.dauer_minuten * 60000;
	const anfang = new Date(zuIso(p.datum, g.von, zone)).getTime();
	const schluss = new Date(zuIso(p.datum, g.bis, zone)).getTime();
	const out = [];
	for (let s = anfang; s + dauer <= schluss && out.length < MAX_VORSCHLAEGE; s += RASTER_MINUTEN * 60000) {
		if (!b.some((x) => x.von < s + dauer && x.bis > s)) {
			out.push({ start_iso: new Date(s).toISOString(), ende_iso: new Date(s + dauer).toISOString(), text: `${datumText(p.datum)}, ${lokal(s, zone).zeit}–${lokal(s + dauer, zone).zeit} Uhr` });
		}
	}
	return out;
}

/** Graph-Body zum Anlegen des Termins (POST /users/{postfach}/events). transactionId verhindert Doppelanlage. */
function ereignis({ termin, slot, zone }) {
	const s = lokal(new Date(slot.start_iso).getTime(), zone);
	const e = lokal(new Date(slot.ende_iso).getTime(), zone);
	const zeilen = [
		`Vorgang: ${termin.vorgangs_id}`,
		termin.kontakt ? `Ansprechpartner: ${termin.kontakt}` : null,
		termin.telefon ? `Telefon: ${termin.telefon}` : null,
		termin.absender ? `E-Mail: ${termin.absender}` : null,
		'',
		'Eingetragen über den Email Process Agent nach Bestätigung im Team.',
	].filter((z) => z !== null);
	const body = {
		subject: `${termin.titel}${termin.kontakt ? ` – ${termin.kontakt}` : ''}`.slice(0, 250),
		start: { dateTime: `${s.datum}T${s.zeit}:00`, timeZone: zone },
		end: { dateTime: `${e.datum}T${e.zeit}:00`, timeZone: zone },
		body: { contentType: 'text', content: zeilen.join('\n') },
		showAs: 'busy',
		transactionId: termin.termin_id,
	};
	if (termin.ort) body.location = { displayName: String(termin.ort).slice(0, 250) };
	return body;
}

function esc(s) {
	return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
}

function wunschText(p) {
	const zeit = p.art === 'exakt' ? `${p.von}–${p.bis} Uhr` : `zwischen ${p.von} und ${p.bis} Uhr`;
